from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    overall = Counter(x for row in grid for x in row)
    dominant = overall.most_common(1)[0][0]

    # The divider is a uniform column whose color is not the grid background.
    candidates = [
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1
        and grid[0][c] != dominant
    ]
    divider = min(candidates, key=lambda c: overall[grid[0][c]])

    left_width = divider
    right_width = w - divider - 1
    width = min(left_width, right_width)
    right_bg = Counter(
        grid[r][divider + 1 + c]
        for r in range(h) for c in range(width)
    ).most_common(1)[0][0]

    return [
        [
            3 if grid[r][c] == grid[r][divider + 1 + c] else right_bg
            for c in range(width)
        ]
        for r in range(h)
    ]
